const constructibleTagNames = new Map<string, string>([
	["CULTURE", "LOC_TAG_CULTURE"],
	["DIPLOMACY", "LOC_TAG_DIPLOMACY"],
	["FOOD", "LOC_TAG_FOOD"],
	["FORTIFICATION", "LOC_TAG_FORTIFICATION"],
	["GOLD", "LOC_TAG_GOLD"],
	["HAPPINESS", "LOC_TAG_HAPPINESS"],
	["MILITARY", "LOC_TAG_MILITARY"],
	["PRODUCTION", "LOC_TAG_PRODUCTION"],
	["SCIENCE", "LOC_TAG_SCIENCE"],
	["WAREHOUSE", "LOC_TAG_WAREHOUSE"],
	["WATER", "LOC_TAG_WATER"],
	["BRIDGE", "LOC_TAG_BRIDGE"],
	["UNIQUE", "LOC_TAG_UNIQUE"],
	["UNIQUE_IMPROVEMENT", "LOC_TAG_UNIQUE_IMPROVEMENT"],
	["AGELESS", "LOC_TAG_AGELESS"],
	["PERSISTENT", "LOC_TAG_PERSISTENT"],
]);

const constructibleTagsToExclude: string[] = [
	"TRADE",
	"SUPPLIES",
	"GREATWORK",
	"RELIGIOUS",
	"DISTRICT_WALL",
	"FULL_TILE",
	"UNIT_FORTIFICATION",
	"IGNORE_DISTRICT_PLACEMENT_CAP",
	"LINK_ADJACENT",
	"DAMAGE_UPON_OCCUPATION",
	"RAIL_CONNECTION",
	"MILL",
	"CRISIS",
	"URBANCENTER",
	"PERSISTENT",
];

export function composeTagString(tags: string[]) {
	let tagText = "";
	for (const tag of tags) {
		if (tagText == "") {
			tagText += tag;
		} else {
			tagText += " | " + tag;
		}
	}
	return tagText;
}

// local cache of constructible type to its set of tags
const constructibleItemTypeMap = new Map<string, Set<string>>();
for (const e of GameInfo.TypeTags) {
	let tagSet = constructibleItemTypeMap.get(e.Type);
	if (!tagSet) {
		tagSet = new Set();
		constructibleItemTypeMap.set(e.Type, tagSet);
	}
	tagSet.add(e.Tag as string);
}

export function getConstructibleTagsFromType(type: string): string[] {
	const tagSet = constructibleItemTypeMap.get(type);
	if (!tagSet) {
		// No tags for the constructuble.  This is not an error, constructibles don't have to have tags.
		return [];
	}

	return Array.from(tagSet)
		.filter((tag) => !constructibleTagsToExclude.includes(tag) && constructibleTagNames.has(tag))
		.map((tag) => Locale.compose(constructibleTagNames.get(tag)!));
}

/** Checks if a constructible has a specific tag type */
export function ConstructibleHasTagType(ConstructibleType: string, TypeTag: string): boolean {
	const tagSet = constructibleItemTypeMap.get(ConstructibleType);
	if (!tagSet) {
		return false;
	}

	return tagSet.has(TypeTag);
}
